 const site = { name: "Komotini", type: "Wind", lat: 41.1170, lon: 25.4044 };

// --- Wind simulation (with cut-in / rated / cut-out) ---
const cutIn = 3;         // m/s
const rated = 12;        // m/s
const cutOut = 25;       // m/s
const capacityKW = 1500; // nameplate

