  const norm = (windSpeed - cutIn) / (rated - cutIn);
  p = capacityKW * Math.pow(norm, 3);               // cubic rise to rated
} else if (windSpeed <= cutOut) {
  p = capacityKW;                                   // flat at rated
} else {
  p = 0;                                            // safety shutdown
}
