const site = { name: "Ioannina", type: "Hydro", lat: 39.6650, lon: 20.8500 };

// --- Hydro simulation (flow, head, efficiency) ---
const hour = new Date().getHours();
const daily = 0.6 + 0.4 * Math.sin((Math.PI * (hour - 6)) / 12); // mild diurnal
const baseFlow = 120;                           // m³/s baseline
const flowCMS = Math.max(40, baseFlow * daily + (Math.random() * 20 - 10)); // 40–~160 m³/s
const headM = 45 + (Math.random() * 6 - 3);   // 42–48 m head
const eta = 0.88 + (Math.random() * 0.04);  // 0.88–0.92 efficiency

// Power P(kW) = ρ g Q H η / 1000  with ρ=1000 kg/m³, g=9.81 m/s²
const power = +((1000 * 9.81 * flowCMS * headM * eta) / 1000).toFixed(0);
const status = Math.random() < 0.02 ? "Fault" : "Running";

