  site: site.name,
  type: site.type,
  power_kW: power,
  flow_cms: +flowCMS.toFixed(1),
  head_m: +headM.toFixed(1),
  efficiency: +eta.toFixed(2),
  status,
  ts: new Date().toISOString(),
  lat: site.lat,
  lon: site.lon
};

