// CheckBefSend v4 — classic node-red-contrib-opcua safe sender (no DB logic)

if (!flow.get("opc_running")) {
  node.status({ fill: "red", shape: "ring", text: "Blocked: server offline" });
  return null;
}

// Unwrap IIoT-style envelope if needed
let m = msg;
if (m && typeof m === "object" && m.payload && m.payload.messageType && !m.messageType) {
  m = m.payload;
}
if (!m || typeof m !== "object") return null;

// Validate core fields
const mtRaw = m.messageType;
const mt    = String(mtRaw || "").toLowerCase();       // 'add' | 'value'
let   name  = (m.variableName || "").trim();
if (!mt || !name) { node.status({ fill:"yellow", shape:"ring", text:"Missing messageType/variableName" }); return null; }

const ns  = (m.namespace == null) ? 1 : Number(m.namespace);
const val = m.variableValue;
const dt  = m.datatype || (typeof val === "number" ? "Double" : "String");

// Build nodeId + de-dup keys
const nodeIdStr = `ns=${ns};s=${name}`;
const epoch     = flow.get("opc_epoch") || 0;                 // bump this in ServerisAlive when server transitions to "running"
const addedKey  = `opc_added::${epoch}::${nodeIdStr}`;
const triesKey  = `opc_tries::${epoch}::${nodeIdStr}`;

// Local caches for pending/last values
const pending = context.get("pending") || {};
const latest  = context.get("latest")  || {};

function emitAdd() {
  node.send({
    topic: `${nodeIdStr};datatype=${dt}`,                     // classic ADD: nodeId+datatype in topic
    payload: { opcuaCommand: "addVariable" }
  });
  node.status({ fill: "blue", shape: "dot", text: `add → ${nodeIdStr}` });
}

function emitSet(v) {
  node.send({
    payload: {
      messageType: "Variable",
      variableName: name,
      namespace: ns,
      datatype: dt,
      variableValue: v
      // optional: sourceTimestamp, quality
    }
  });
  node.status({ fill: "green", shape: "dot", text: `set → ${nodeIdStr}` });
}

// ----- Handle 'add' explicitly -----
if (mt === "add") {
  if (!flow.get(addedKey)) {
    flow.set(addedKey, true);
    flow.set(triesKey, 0);
    emitAdd();
  }
  return null;
}

// ----- Handle 'value' -----
if (mt === "value") {
  // Lazy init tries counter
  let tries = flow.get(triesKey);
  if (typeof tries !== "number") tries = 0;

  // If not added in this epoch, add now
  if (!flow.get(addedKey)) {
    flow.set(addedKey, true);
    flow.set(triesKey, 0);
    emitAdd();
    // queue and delay first set to avoid race
    latest[nodeIdStr]  = val;
    pending[nodeIdStr] = true;
    context.set("latest", latest);
    context.set("pending", pending);
    setTimeout(() => {
      const _p = context.get("pending") || {};
      const _l = context.get("latest")  || {};
      const v  = _l[nodeIdStr];
      emitSet(v);
      delete _p[nodeIdStr];
      context.set("pending", _p);
    }, 900); // increase to 1200ms if still racing
    return null;
  }

  // Already added — but for extra safety, re-emit ADD before first few SETs
  if (tries < 3) {
    emitAdd();                // harmless if it already exists
    flow.set(triesKey, tries + 1);
  }

  // If another delayed SET is pending, just update latest and let the timer fire
  if (pending[nodeIdStr]) {
    latest[nodeIdStr] = val;
    context.set("latest", latest);
    return null;
  }

  // Normal immediate SET
  emitSet(val);
  return null;
}

// Unknown type → ignore
node.status({ fill:"grey", shape:"ring", text:`Ignored mt=${mt}` });
return null;

// Save whether the server is running
if (msg.status && msg.status.text) {
    const running = msg.status.text.toLowerCase().includes("running");
    flow.set("opc_running", running);
    node.status({
        fill: running ? "green" : "red",
        shape: "dot",
        text: running ? "Server running" : "Server down"
    });
}
return null;

