// ToClassicOPCUA (for classic node-red-contrib-opcua Server)
// Converts your {messageType:'add'|'value', namespace, variableName, variableValue, datatype}
// into the shapes the classic server expects.

// 0) optional guard
if (!flow.get("opc_running")) {
  node.status({ fill: "red", shape: "ring", text: "Blocked: server offline" });
  return null;
}

// 1) unwrap if your functions sent OPC fields under payload
let m = msg;
if (m && typeof m === "object" && m.payload && m.payload.messageType && !m.messageType) {
  m = m.payload;
}
if (!m || typeof m !== "object") return null;

const mt = String(m.messageType || "").toLowerCase(); // 'add' or 'value'
const ns = (m.namespace == null) ? 1 : Number(m.namespace);
const name = m.variableName;
const val = m.variableValue;
const dt = m.datatype || (typeof val === "number" ? "Double" : "String");

if (!mt || !name) {
  node.status({ fill: "yellow", shape: "ring", text: "Missing messageType/variableName" });
  return null;
}

const nodeId = `ns=${ns};s=${name}`;
const addedKey = `opc_added::${nodeId}`;
const alreadyAdded = !!flow.get(addedKey);
const out = [];

// --- ADD (one time only) ---
// Classic server wants: topic="ns=1;s=Name;datatype=Double", payload={opcuaCommand:"addVariable"}
if (mt === "add" && !alreadyAdded) {
  out.push({
    topic: `${nodeId};datatype=${dt}`,
    payload: { opcuaCommand: "addVariable" }
  });
  flow.set(addedKey, true);
}

// --- VALUE UPDATE ---
// Classic server wants: payload = { messageType:"Variable", variableName, namespace, datatype, variableValue }
if (mt === "value") {
  if (!alreadyAdded) {
    // lazy-add once before first set
    out.push({
      topic: `${nodeId};datatype=${dt}`,
      payload: { opcuaCommand: "addVariable" }
    });
    flow.set(addedKey, true);
  }
  out.push({
    payload: {
      messageType: "Variable",
      variableName: name,
      namespace: ns,
      datatype: dt,
      variableValue: val
      // optional: sourceTimestamp, quality
    }
  });
}

if (!out.length) return null;

node.status({ fill: "green", shape: "dot", text: `${mt} → ${nodeId}` });
return out;
